const result = $input.item.json;
const watch = $('Watch List').item.json;
const offers = result.offers || [];
if (!offers.length) return [{ json: { alert: false, label: watch.label } }];
const best = offers.reduce((a,b) => a.price.net_raw < b.price.net_raw ? a : b);
const alert = best.price.net_raw <= watch.threshold;
return [{ json: {
  alert,
  label: watch.label,
  route: `${watch.origin} → ${watch.destination}`,
  date: watch.date,
  net: best.price.net_usd,
  client: best.price.client_price_usd,
  carrier: best.itineraries[0].segments[0].carrier,
  flight: best.itineraries[0].segments[0].flight_number,
  departs: best.itineraries[0].segments[0].departure_time,
  threshold: watch.threshold
}}];
